select jsonb_build_object(
 'functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',coalesce(p.proacl::text,'')) order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('admin_get_or_create_renewal_test_account','admin_ensure_renewal_test_account_profile','admin_prepare_renewal_test_scenario','admin_reset_renewal_test_scenario','admin_restore_renewal_test_scenario','admin_seed_renewal_test_registration_documents','enforce_accreditation_immutability','sync_organization_accreditation_projection','calculate_organization_renewal_eligibility','derive_accreditation_status','validate_admin_session_token')),
 'columns',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where a.attnum>0 and not a.attisdropped and ((n.nspname='public' and c.relname in ('organization_profiles','organization_accreditations','organization_renewals','admin_accounts','roles','activity_logs','budget_requests','liquidation_reports')) or (n.nspname='auth' and c.relname='users'))),
 'constraints',(select jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid)) order by c.conrelid::regclass::text,c.conname) from pg_constraint c where c.conrelid in ('public.organization_profiles'::regclass,'public.organization_accreditations'::regclass,'public.organization_renewals'::regclass,'public.activity_logs'::regclass)),
 'indexes',(select jsonb_agg(jsonb_build_object('name',indexname,'definition',indexdef) order by indexname) from pg_indexes where schemaname='public' and tablename='organization_accreditations'),
 'triggers',(select jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid)) order by t.tgname) from pg_trigger t where t.tgrelid='public.organization_accreditations'::regclass and not t.tgisinternal),
 'roles',(select jsonb_agg(jsonb_build_object('name',rolname,'super',rolsuper,'inherit',rolinherit,'login',rolcanlogin,'bypass',rolbypassrls) order by rolname) from pg_roles where rolname in ('postgres','anon','authenticated','service_role')),
 'storage',(select jsonb_agg(jsonb_build_object('name',policyname,'cmd',cmd,'roles',roles,'permissive',permissive,'qual',qual,'check',with_check) order by policyname) from pg_policies where schemaname='storage' and tablename='objects'),
 'grants',(select jsonb_agg(jsonb_build_object('table',c.oid::regclass::text,'owner',pg_get_userbyid(c.relowner),'acl',coalesce(c.relacl::text,''),'rls',c.relrowsecurity,'force',c.relforcerowsecurity) order by c.oid::regclass::text) from pg_class c where c.oid in ('public.organization_accreditations'::regclass,'public.organization_profiles'::regclass,'public.organization_renewals'::regclass,'public.activity_logs'::regclass,'storage.objects'::regclass))
) manifest;
